import{j as e}from"./blog-pages-Bhdy2a24.js";import{M as i}from"./MethodCoursePage-eAc05vzC.js";const n={slug:"asnt-level-2-ut-online-course",seoTitle:"ASNT Level 2 UT Online Course — Certification Pathway & Exam Prep | Atlantis NDT",seoDescription:"ASNT Level 2 UT online course: ultrasonic testing theory online, hands-on practical on-site, SNT-TC-1A/NAS 410 pathway. ~80 classroom hours. Online + on-site + hybrid. Free consultation.",keywords:"ASNT Level 2 UT online course, UT Level II certification, ultrasonic testing Level 2 course, SNT-TC-1A UT training, NAS 410 UT Level II, ASNT UT online training",h1:"ASNT Level 2 UT Online Course",badgeLabel:"ASNT Level II Certification Pathway",heroSubtitle:"Ultrasonic Testing (UT) Level II training built around SNT-TC-1A and NAS 410 requirements — online theory, hands-on practical, and a documented route to Level II certification for working inspectors.",methodName:"Ultrasonic Testing (UT)",levelLabel:"Level II",hoursLabel:"≈80 classroom hours for Level II (in addition to Level I hours already completed), per SNT-TC-1A recommended training-hour guidance.",stats:[{label:"Certification Level",value:"Level II"},{label:"Typical Hours",value:"≈80 hrs"},{label:"Recert Cycle",value:"5 Years"},{label:"Delivery",value:"Online + On-site"}],overview:["Ultrasonic Testing (UT) uses high-frequency sound waves to detect internal flaws, measure wall thickness, and evaluate weld quality without damaging the component being inspected. A UT Level II technician works independently: setting up and calibrating equipment, selecting technique, interpreting A-scan and digital thickness readings, sizing and characterizing flaws, and writing inspection reports that a Level III can review and sign off on.","The ASNT Level 2 UT online course covers the theory layer of that scope — sound-wave propagation, transducer behavior, calibration-block use, DAC/DGS curve construction, and code-based accept/reject criteria — through self-paced online modules, while the hands-on scanning and equipment-calibration practical is delivered on-site, because UT proficiency cannot be certified from theory alone.","This course sits inside Atlantis NDT's broader multi-scheme training catalogue (ASNT SNT-TC-1A, ISO 9712, NAS 410, and API ICP-adjacent inspector pathways), delivered by ASNT NDT Level III-led instruction with a 96% first-attempt pass rate across cohorts since 2019."],highlightTitle:"Why Level II Matters",highlightBody:"Level I technicians perform UT under the supervision of a Level II or III. Level II certification is what lets you work independently — setting up equipment, choosing technique, interpreting results, and issuing reports — making it the qualification most inspection companies actually hire and promote against.",curriculum:["Sound-wave theory, propagation modes and attenuation","Transducer types, frequency selection and beam characteristics","Calibration blocks (IIW, DSC) and DAC/DGS curve construction","Digital thickness gauging and A-scan interpretation","Weld scanning technique per ASME Section V Article 4/5","Flaw detection, sizing and characterization","Couplants, surface preparation and scan indexing","Code interpretation — accept/reject per ASME VIII and B31.3","Report writing and Level I supervision responsibilities","Calibration verification and equipment maintenance checks"],pathwaySteps:[{title:"Eligibility & vision screening",detail:"Confirm your Level I UT certification (or equivalent documented experience) and complete a current Jaeger J-2 near-vision and colour-vision screening — required annually under SNT-TC-1A."},{title:"Formal Level II training",detail:"Complete the online theory modules, then the on-site hands-on practical covering calibration, scanning technique and flaw sizing on representative test pieces."},{title:"General, specific and practical examination",detail:"Sit the written and practical exam administered per your employer's SNT-TC-1A written practice (or an accredited scheme's exam structure for ISO 9712 / NAS 410 candidates)."},{title:"Certification issued and documented",detail:"Your Level II UT certification is documented in your personnel record along with training hours, exam scores, and vision-test results."},{title:"5-year recertification cycle",detail:"Your certification runs on a 5-year SNT-TC-1A/CP-189 cycle, with an annual vision test required on a separate, shorter clock."}],faqs:[{question:"Is the ASNT Level 2 UT course fully online?",answer:"The theory portion — sound-wave physics, calibration principles, code interpretation — is delivered online and self-paced. The hands-on scanning, calibration and practical assessment must be done in person, because UT is an equipment-based method and no certifying scheme accepts practical competency demonstrated purely online. We call this a blended or hybrid format: online theory, on-site practical."},{question:"What is the difference between UT Level I and Level II?",answer:"Level I technicians perform specific calibrations, conduct tests and record results under the supervision of a Level II or III, following documented procedures. Level II technicians work independently — they set up and calibrate equipment, select technique, interpret and evaluate results per applicable codes, and organize and report inspection results. Level II is the qualification most employers require for unsupervised UT work."},{question:"How many hours does the ASNT Level 2 UT course take?",answer:"SNT-TC-1A recommended training-hour guidance puts UT Level II at roughly 80 classroom hours, in addition to the hours already completed at Level I, plus documented on-the-job experience hours specific to the method. Actual hours can vary by your prior experience and the certifying scheme (ASNT SNT-TC-1A, ISO 9712, or NAS 410 for aerospace work)."},{question:"Do I need a Level I certification before taking Level II?",answer:"Yes — Level II builds directly on Level I. You'll need a current UT Level I certification, or equivalent documented training and experience accepted under your employer's written practice, before enrolling in the Level II pathway."},{question:"How long is ASNT UT Level II certification valid?",answer:"UT Level II certification runs on a 5-year SNT-TC-1A or CP-189 recertification cycle. Separately, an annual vision test (near-vision and colour-vision screening) is required on a shorter clock than the certification itself — it's the single most common thing that lapses unnoticed. See our NDT Level 2 recertification / renewal course when your cycle approaches."},{question:"Can this course lead to NAS 410 certification for aerospace work?",answer:"Yes. The same UT fundamentals apply under NAS 410 (and EN 4179 in Europe) for aerospace-sector candidates — the pathway structure differs slightly in documentation and employer-specific written practice requirements, which we cover as part of enrollment scoping."}],relatedLinks:[{to:"/paut-level-2-training-course",label:"PAUT Level 2 Training Course",desc:"Advanced phased-array UT for weld and corrosion mapping"},{to:"/tofd-training-certification-course",label:"TOFD Training & Certification",desc:"Time-of-flight diffraction for precision flaw sizing"},{to:"/asnt-certification",label:"ASNT Certification Guide",desc:"Full Level I/II/III pathway across all methods"}],courseName:"ASNT Level II Ultrasonic Testing (UT) Course",courseDescription:"Ultrasonic Testing Level II training covering sound-wave theory, calibration, thickness gauging, weld flaw detection and sizing, and SNT-TC-1A Level II reporting responsibilities. Online theory with on-site practical assessment.",courseTeaches:"Ultrasonic testing principles, equipment calibration, A-scan interpretation, thickness gauging, weld flaw detection and sizing, and SNT-TC-1A Level II reporting responsibilities",coursePrerequisites:"UT Level I certification (or equivalent documented experience) plus a current Jaeger J-2 near-vision and colour-vision screening",educationalCredentialAwarded:"Level II Ultrasonic Testing certificate of training completion, documented per SNT-TC-1A / employer written practice",educationalLevel:"Professional",durationISO:"PT80H",articleHeadline:"ASNT Level 2 UT Online Course: Certification Pathway, Hours & Exam Structure",articleDescription:"What the ASNT Level 2 UT online course covers, how many hours it takes, the SNT-TC-1A/NAS 410 certification pathway, and how online theory pairs with on-site practical training.",articleSection:"NDT Training",articleKeywords:"ASNT Level 2 UT, UT Level II, ultrasonic testing certification, SNT-TC-1A, NAS 410"};function r(){return e.jsx(i,{data:n})}export{r as default};
